-- Optional manual migration; the module can also initialize this table automatically.
CREATE TABLE IF NOT EXISTS commerce_directory (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,local_number VARCHAR(60) NOT NULL DEFAULT '',image VARCHAR(255) NULL,description TEXT NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,featured TINYINT(1) NOT NULL DEFAULT 0,sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NULL DEFAULT NULL,UNIQUE KEY uq_commerce_user(user_id),INDEX idx_commerce_public(active,featured,sort_order),CONSTRAINT fk_directory_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
